<script setup>
import {computed,onMounted,ref} from 'vue';import {get,fmt,pct} from '../api/client';import DataTable from '../components/DataTable.vue';import StockHistoryModal from '../components/StockHistoryModal.vue';
const modelNames={multi_factor_rank:'次日方向模型',tradeable_t1_open:'T+1可交易模型'},runs=ref([]),activeModel=ref('multi_factor_rank'),selected=ref({}),data=ref({candidates:[],factors:[]}),view=ref('candidates'),ranking=ref({items:[],total:0,page:1,pages:1}),showLogic=ref(false),showAdvanced=ref(false),historyStock=ref(null),loading=ref(false);
const filter=ref({keyword:'',market:'',rank_min:'',rank_max:'',probability_min:'',candidate_only:false,sort:'full_ranking',order:'asc'}),modelRuns=computed(()=>runs.value.filter(r=>r.model_code===activeModel.value)),isTradeable=computed(()=>activeModel.value==='tradeable_t1_open');
async function load(){const id=selected.value[activeModel.value];if(!id){data.value={candidates:[],factors:[]};return}data.value=await get(`/predictions/${id}/candidates`);if(view.value==='rankings')await loadRankings(1)}
async function loadRankings(page=ranking.value.page||1){const id=selected.value[activeModel.value];if(!id)return;loading.value=true;try{const query=new URLSearchParams({page:String(page),page_size:'50',sort:filter.value.sort,order:filter.value.order});for(const key of ['keyword','market','rank_min','rank_max','probability_min'])if(filter.value[key]!==''&&filter.value[key]!=null)query.set(key,filter.value[key]);if(filter.value.candidate_only)query.set('candidate_only','true');ranking.value=await get(`/predictions/${id}/rankings?${query}`)}finally{loading.value=false}}
async function switchModel(code){activeModel.value=code;showLogic.value=false;await load()}async function switchView(value){view.value=value;if(value==='rankings')await loadRankings(1)}
onMounted(async()=>{runs.value=await get('/predictions');for(const code of Object.keys(modelNames))selected.value[code]=runs.value.find(r=>r.model_code===code)?.id;await load()});
const change=v=>v==null?'—':v>0?`↑${v}`:v<0?`↓${Math.abs(v)}`:'持平';
const candidateCore=[{label:'代码',key:'stock_code',action:r=>historyStock.value=r},{label:'名称',key:'stock_name'},{label:'市场',key:'market'},{label:'候选排名',key:'ranking'},{label:'排名变化',key:'full_ranking_change',sortValue:r=>r.full_ranking_change??r.ranking_change,format:(v,r)=>change(v??r.ranking_change)},{label:'近5期入选',key:'recent_5_count',format:(v,r)=>`${v}/${r.recent_5_periods}`},{label:'上涨概率',key:'up_probability',format:pct,defaultDirection:-1},{label:'预计收益',key:'expected_return',format:pct,defaultDirection:-1},{label:'评分',key:'score',format:v=>fmt(v,3),defaultDirection:-1}];
const candidateAdvanced=[{label:'上期排名',key:'previous_full_ranking',sortValue:r=>r.previous_full_ranking??r.previous_ranking,format:(v,r)=>v??r.previous_ranking??'—'},{label:'概率变化',key:'probability_change',format:v=>v==null?'—':`${v>=0?'+':''}${pct(v)}`},{label:'90%收益区间',key:'return_low_90',format:(v,r)=>v==null?'—':`${pct(v)} ~ ${pct(r.return_high_90)}`},{label:'置信度',key:'prediction_confidence',format:pct}];
const candidateColumns=computed(()=>showAdvanced.value?[...candidateCore,...candidateAdvanced]:candidateCore);
const rankingCore=[{label:'代码',key:'stock_code',action:r=>historyStock.value=r},{label:'名称',key:'stock_name'},{label:'市场',key:'market'},{label:'完整排名',key:'full_ranking'},{label:'排名变化',key:'full_ranking_change',format:change},{label:'候选状态',key:'is_candidate',format:v=>v?'Top30':'—'},{label:'评分',key:'score',format:v=>fmt(v,3)},{label:'上涨概率',key:'up_probability',format:pct},{label:'预计收益',key:'expected_return',format:pct}];
const rankingAdvanced=[{label:'上期排名',key:'previous_full_ranking'},{label:'当日涨跌',key:'daily_return',format:pct},{label:'近5日涨跌',key:'return_5d',format:pct},{label:'量比20日',key:'volume_ratio_20',format:v=>fmt(v,2)},{label:'近20日平均成交额(亿)',key:'avg_amount_20',format:v=>fmt(v/1e8,2)}];
const rankingColumns=computed(()=>showAdvanced.value?[...rankingCore,...rankingAdvanced]:rankingCore);
const factors=[{label:'因子',key:'factor_name'},{label:'权重',key:'model_weight',format:pct},{label:'平均IC',key:'mean_ic',format:v=>fmt(v,4)},{label:'正IC比例',key:'positive_ic_rate',format:pct},{label:'有效样本期数',key:'valid_trade_days'}];
</script>
<template><div class="model-tabs"><button v-for="(name,code) in modelNames" :key="code" :class="{active:activeModel===code}" @click="switchModel(code)">{{name}}</button></div>
<div class="prediction-toolbar"><select v-if="modelRuns.length" v-model="selected[activeModel]" @change="load"><option v-for="r in modelRuns" :key="r.id" :value="r.id">预测基准日 {{r.base_date}} · {{r.model_version}}</option></select><span v-else>该模型暂无预测批次</span><button @click="showLogic=!showLogic">{{showLogic?'收起选股逻辑':'查看选股逻辑'}}</button></div>
<div class="experimental-note"><template v-if="isTradeable"><b>T+1可交易口径：</b>下一交易日开盘模拟买入，再下一交易日开盘模拟卖出。</template><template v-else><b>次日方向口径：</b>信号日收盘至下一交易日收盘。</template></div>
<div v-if="showLogic" class="card logic-card"><h2>{{modelNames[activeModel]}}计算逻辑</h2><ol><li>九个行情因子按各自目标独立计算动态权重。</li><li>全部有效股票先形成完整排名，再截取Top30正式候选。</li><li>完整排名只用于解释和趋势分析，不改变模型评分、盘中观察或正式验证。</li></ol></div>
<div class="section-heading section"><div class="model-tabs"><button :class="{active:view==='candidates'}" @click="switchView('candidates')">正式候选 Top30</button><button :class="{active:view==='rankings'}" @click="switchView('rankings')">全部有效股票排名</button></div><button @click="showAdvanced=!showAdvanced">{{showAdvanced?'隐藏高级列':'显示高级列'}}</button></div>
<template v-if="view==='candidates'"><p v-if="!data.has_full_ranking" class="notice">该历史批次生成时尚未保存完整排名；从下一次预测开始积累完整排名趋势。</p><p v-else-if="!data.has_full_ranking_history" class="notice">当前只有 {{data.full_ranking_periods}} 期完整排名；排名变化暂时使用已有Top30历史，下一期后自动使用完整排名历史。</p><p class="hint">排名变化优先使用完整排名；完整历史不足时回退到候选排名变化，无法比较时留空。</p><DataTable :columns="candidateColumns" :rows="data.candidates"/><div class="section"><h2>因子权重</h2><DataTable :columns="factors" :rows="data.factors"/></div></template>
<template v-else><div class="toolbar ranking-filter"><input v-model="filter.keyword" placeholder="股票代码或名称"><select v-model="filter.market"><option value="">全部市场</option><option>SH</option><option>SZ</option><option>BJ</option></select><input v-model="filter.rank_min" type="number" min="1" placeholder="最低排名"><input v-model="filter.rank_max" type="number" min="1" placeholder="最高排名"><input v-model="filter.probability_min" type="number" min="0" max="1" step="0.01" placeholder="最低上涨概率"><label><input v-model="filter.candidate_only" type="checkbox">仅Top30</label><select v-model="filter.sort"><option value="full_ranking">按排名</option><option value="score">按评分</option><option value="up_probability">按上涨概率</option><option value="expected_return">按预期收益</option></select><select v-model="filter.order"><option value="asc">升序</option><option value="desc">降序</option></select><button @click="loadRankings(1)">查询</button></div><p class="hint">共 {{ranking.total}} 只有效股票；排序作用于全部结果，完整排名数据从功能上线后的新预测开始积累。</p><div v-if="loading" class="empty">正在加载…</div><DataTable v-else :columns="rankingColumns" :rows="ranking.items" :sortable="false"/><div class="pager"><button :disabled="ranking.page<=1" @click="loadRankings(ranking.page-1)">上一页</button><span>第 {{ranking.page}} / {{ranking.pages}} 页</span><button :disabled="ranking.page>=ranking.pages" @click="loadRankings(ranking.page+1)">下一页</button></div></template><StockHistoryModal :stock="historyStock" @close="historyStock=null"/></template>
